package com.typewritermc.codegen

import com.squareup.kotlinpoet.AnnotationSpec
import com.squareup.kotlinpoet.ClassName
import com.squareup.kotlinpoet.FileSpec

/** Builds every generated Kotlin file with the same header. */
internal object GeneratedFile {
    /** Every generated file opts into generator hooks once and suppresses the casts KClass tokens require. */
    fun builder(
        packageName: String,
        name: String,
    ): FileSpec.Builder =
        FileSpec
            .builder(packageName, name)
            .indent("    ")
            .addFileComment("Generated by Typewriter codegen. Edit the source declaration, not this file.")
            .addAnnotation(
                AnnotationSpec
                    .builder(OPT_IN)
                    .addMember("%T::class", GENERATED_SDK_API)
                    .useSiteTarget(AnnotationSpec.UseSiteTarget.FILE)
                    .build(),
            ).addAnnotation(
                AnnotationSpec
                    .builder(Suppress::class)
                    .addMember("%S", "UNCHECKED_CAST")
                    .useSiteTarget(AnnotationSpec.UseSiteTarget.FILE)
                    .build(),
            )
}

/**
 * `kotlin.OptIn` and the `@RequiresOptIn` marker `GeneratedSdkApi` cannot be used as class literals outside an
 * annotation, so they are named here.
 */
private val OPT_IN = ClassName("kotlin", "OptIn")
private val GENERATED_SDK_API = ClassName("com.typewritermc.authoring", "GeneratedSdkApi")
